python3 <<'EOF'
def lum(hex_color):
    hex_color = hex_color.lstrip('#')
    r, g, b = (int(hex_color[i:i+2], 16)/255 for i in (0,2,4))
    def lin(c):
        return c/12.92 if c <= 0.03928 else ((c+0.055)/1.055)**2.4
    r, g, b = lin(r), lin(g), lin(b)
    return 0.2126*r + 0.7152*g + 0.0722*b

def contrast(c1, c2):
    l1, l2 = lum(c1), lum(c2)
    l1, l2 = max(l1, l2), min(l1, l2)
    return (l1 + 0.05) / (l2 + 0.05)

candidates = ["#6a5fd6", "#5c50c9", "#5951c4", "#5147bd", "#4a3fb8", "#453aae"]
bgs = {"baby-blue": "#d7ecfb", "mint": "#d4f3e4", "lavender": "#e6defa"}
for c in candidates:
    row = [f"{name}={contrast(c,bg):.2f}" for name, bg in bgs.items()]
    print(c, row)
EOF

